import {
  Global,
  Inject,
  Injectable,
  Logger,
  Module,
  Optional,
} from '@nestjs/common';
import { AppConfig } from '../config/app-config.js';
import { Errors } from '../common/errors.js';
import { MetricsService } from '../metrics/metrics.service.js';
import { LocalStorageDriver } from './local-storage.driver.js';
import { R2StorageDriver } from './r2-storage.driver.js';
import {
  STORAGE_DRIVER,
  type PutObjectOptions,
  type StorageDriver,
  type StoredObjectInfo,
} from './storage.types.js';

/**
 * Keys are generated by the server only. This pattern is checked on every operation so
 * a bug elsewhere can never turn into "delete/overwrite an arbitrary object".
 */
const SAFE_KEY = /^[a-z0-9][a-z0-9-]{0,62}(?:\/[a-z0-9][a-z0-9._-]{0,120})+$/;

export function assertSafeKey(key: string): void {
  if (key.length > 512 || !SAFE_KEY.test(key) || key.includes('..'))
    throw new Error(`Refusing unsafe storage key "${key.slice(0, 80)}"`);
}

/**
 * Object storage facade: validates keys, logs every operation as structured JSON-able
 * fields (never credentials or object bodies) and counts results for /metrics.
 */
@Injectable()
export class StorageService {
  private readonly logger = new Logger(StorageService.name);

  constructor(
    @Optional()
    @Inject(STORAGE_DRIVER)
    private readonly driver: StorageDriver | null,
    private readonly metrics: MetricsService,
  ) {}

  get enabled(): boolean {
    return Boolean(this.driver);
  }

  /** 'R2' | 'LOCAL'; throws 503 when storage is not configured. */
  get provider(): StorageDriver['provider'] {
    return this.require().provider;
  }

  private require(): StorageDriver {
    if (!this.driver)
      throw Errors.unavailable(
        'MEDIA_STORAGE_NOT_CONFIGURED',
        'Image uploads are not configured on this server.',
      );
    return this.driver;
  }

  async put(key: string, body: Buffer, opts: PutObjectOptions): Promise<void> {
    assertSafeKey(key);
    await this.run('put', key, () => this.require().put(key, body, opts), {
      bytes: body.length,
      contentType: opts.contentType,
    });
  }

  head(key: string): Promise<StoredObjectInfo | null> {
    assertSafeKey(key);
    return this.run('head', key, () => this.require().head(key));
  }

  async delete(key: string): Promise<void> {
    assertSafeKey(key);
    await this.run('delete', key, () => this.require().delete(key));
  }

  /** Deletes every key, attempting all of them; rejects with the first error afterwards. */
  async deleteMany(keys: string[]): Promise<void> {
    const results = await Promise.allSettled(keys.map((k) => this.delete(k)));
    const failed = results.find(
      (r): r is PromiseRejectedResult => r.status === 'rejected',
    );
    if (failed) throw failed.reason;
  }

  publicUrl(key: string): string {
    assertSafeKey(key);
    return this.require().publicUrl(key);
  }

  private async run<T>(
    op: string,
    key: string,
    fn: () => Promise<T>,
    extra: Record<string, unknown> = {},
  ): Promise<T> {
    const started = performance.now();
    try {
      const out = await fn();
      this.metrics.storageOps.inc({ op, result: 'ok' });
      this.logger.debug({
        msg: 'storage op',
        op,
        key,
        provider: this.driver?.provider,
        ms: Math.round(performance.now() - started),
        ...extra,
      });
      return out;
    } catch (err) {
      this.metrics.storageOps.inc({ op, result: 'error' });
      const e = err as {
        name?: string;
        message?: string;
        $metadata?: { httpStatusCode?: number; requestId?: string };
      };
      this.logger.warn({
        msg: 'storage op failed',
        op,
        key,
        provider: this.driver?.provider,
        ms: Math.round(performance.now() - started),
        error: e?.name,
        status: e?.$metadata?.httpStatusCode,
        requestId: e?.$metadata?.requestId,
        detail: e?.message?.slice(0, 200),
      });
      throw err;
    }
  }
}

export function createStorageDriver(config: AppConfig): StorageDriver | null {
  switch (config.mediaStorage) {
    case 'r2':
      return new R2StorageDriver(config.r2!);
    case 'local':
      return new LocalStorageDriver(
        config.mediaLocalDir,
        config.mediaLocalPublicUrl,
      );
    default:
      return null;
  }
}

@Global()
@Module({
  providers: [
    {
      provide: STORAGE_DRIVER,
      inject: [AppConfig],
      useFactory: createStorageDriver,
    },
    StorageService,
  ],
  exports: [StorageService, STORAGE_DRIVER],
})
export class StorageModule {}
